sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // implement resource here

    var token = request.body.data.grc;

	// gs.info("Token "+JSON.stringify(request.body.data));

    var secret = gs.getProperty('x_1097288_hacktaho.hackathon.google.captcha.secret');

    var r = new sn_ws.RESTMessageV2();
    r.setEndpoint('https://www.google.com/recaptcha/api/siteverify');
    r.setHttpMethod('POST');
    r.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");
    r.setRequestBody("secret=" + encodeURIComponent(secret) + "&response=" + encodeURIComponent(token));

    var googleResponse = r.execute();
    var result = JSON.parse(googleResponse.getBody());

	// gs.info(JSON.stringify(result));
	// result.success = true;

    if (result.success) {
		// gs.info("TEST:"+request.body.data.portal_id);
		var hackathonRegistraitonUtils = new HackathonExternalUserManagmentUtils(request.body.data.portal_id);
		var hackathonResponse = JSON.parse(hackathonRegistraitonUtils.registerUser(request.body.data));

		gs.getSession().putClientData("reg_resp_message",hackathonResponse.message_txt);
        gs.getSession().putClientData("reg_resp_status",hackathonResponse.status);
        gs.getSession().putClientData("reg_user_name",request.body.data.email);

		// gs.info("TESTRUB"+JSON.stringify(hackathonResponse));

		return hackathonResponse;

        // return {
        //     message: HackathonExternalRegConstants.SUCCESS_REQ,
        //     message_text: HackathonExternalRegConstants.SUCCESS_REQ_MESSAGE,
        //     status: HackathonExternalRegConstants.SUCCESS
        // };
    } else {
        return {
			message: HackathonGoogleCaptchaUtils.INVALID_GRC,
			message_text: HackathonGoogleCaptchaUtils.INVALID_GRC_MESSAGE,
			status: HackathonGoogleCaptchaUtils.ERROR
		};
    }

})(request, response);
